import java.util.*;

class RunningMedian {
    private final PriorityQueue<Integer> low = new PriorityQueue<>(Collections.reverseOrder()); // lower half, max on top
    private final PriorityQueue<Integer> high = new PriorityQueue<>();                          // upper half, min on top

    public RunningMedian() {}

    public void addNum(int num) {
        low.offer(num);
        high.offer(low.poll());                 // keep every low <= every high
        if (high.size() > low.size()) low.offer(high.poll()); // low may hold one extra
    }

    public double findMedian() {
        if (low.size() > high.size()) return low.peek();
        return ((long) low.peek() + high.peek()) / 2.0;
    }
}

